79	impl FileOrRedirect {
80	  fn from_deno_cache_entry(
81	    url: &Url,
82	    cache_entry: CacheEntry,
83	  ) -> Result<Self, RedirectResolutionError> {
84	    if let Some(redirect_to) = cache_entry.metadata.headers.get("location") {
85	      let redirect =
86	        url
87	          .join(redirect_to)
88	          .map_err(|source| RedirectResolutionError {
89	            url: url.clone(),
90	            location: redirect_to.clone(),
91	            source,
92	          })?;
93	      Ok(FileOrRedirect::Redirect(redirect))
94	    } else {
95	      Ok(FileOrRedirect::File(File {
96	        url: url.clone(),
97	        mtime: None,
98	        maybe_headers: Some(cache_entry.metadata.headers),
99	        #[allow(clippy::disallowed_types, reason = "ok for source")]
100	        source: std::sync::Arc::from(cache_entry.content),
101	        loaded_from: LoadedFrom::Cache,
102	      }))
103	    }
104	  }
105	}
